// orders are documents; an order embeds its line items array
async function addLineItem(orderId, item) {
  const order = await docs.get('orders', orderId);   // read whole document
  order.items.push(item);                            // mutate in memory
  order.total = order.items.reduce((s, i) => s + i.price * i.qty, 0);
  await docs.put('orders', orderId, order);          // write whole document back
}

// the catalog price lives inside every order document that references the product
async function setProductPrice(productId, newPrice) {
  const affected = await docs.scan('orders');        // read all order docs
  for (const o of affected) {
    for (const li of o.items) {
      if (li.productId === productId) li.price = newPrice;
    }
    await docs.put('orders', o.id, o);
  }
}
